head.b:skin:
/*
-----------------------------------------------
Blogger theme — Daily Yield
-----------------------------------------------
<Group description="Palette" selector="body">
 <Variable name="keycolor" description="Accent gold" type="color" default="#BC5B33" value="#BC5B33"/>
 <Variable name="bg.color" description="Page background" type="color" default="#F8F0E3" value="#F8F0E3"/>
 <Variable name="surface.color" description="Card surface" type="color" default="#FFFDF8" value="#FFFDF8"/>
 <Variable name="ink.color" description="Primary text" type="color" default="#241610" value="#241610"/>
 <Variable name="muted.color" description="Secondary text" type="color" default="#7A6A58" value="#7A6A58"/>
 <Variable name="accent.color" description="Accent" type="color" default="#BC5B33" value="#BC5B33"/>
 <Variable name="accent.dark.color" description="Accent (hover)" type="color" default="#9C4522" value="#9C4522"/>
 <Variable name="accent.soft.color" description="Accent tint" type="color" default="#F6E3D3" value="#F6E3D3"/>
 <Variable name="line.color" description="Hairlines and borders" type="color" default="#EADCC8" value="#EADCC8"/>
 <Variable name="footer.bg.color" description="Footer background" type="color" default="#1D1109" value="#1D1109"/>
</Group>
<Group description="Typography" selector="body">
 <Variable name="body.family" description="Body font family" type="string" default="Inter" value="Inter"/>
<Variable name="heading.family" description="Heading font family" type="string" default="Playfair Display" value="Playfair Display"/>
</Group>
*/

/* ============ 0. Tokens ============ */
:root{
 --paper:$(bg.color);
 --surface:$(surface.color);
 --ink:$(ink.color);
 --muted:$(muted.color);
 --accent:$(accent.color);
 --accent-dark:$(accent.dark.color);
 --accent-soft:$(accent.soft.color);
 --line:$(line.color);
 --footer-bg:$(footer.bg.color);
 --font-body:"$(body.family)",-apple-system,BlinkMacSystemFont,"Segoe UI",Helvetica,Arial,sans-serif;
 --font-display:"$(heading.family)",Georgia,"Times New Roman",serif;
 --ease:cubic-bezier(.22,.61,.36,1);
}

/* ============ 1. Foundation ============ */
*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%;text-size-adjust:100%}
html.drawer-open,html.drawer-open body,html.search-open body{overflow:hidden}
body{margin:0;background:var(--paper);color:var(--ink);font:400 16.5px/1.78 var(--font-body);-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility;-webkit-text-size-adjust:100%;text-size-adjust:100%;max-width:100%;overflow-x:clip}
img{max-width:100%;height:auto;display:block}
a{color:inherit;text-decoration:none}
button{font:inherit;color:inherit;background:none;border:0;cursor:pointer;padding:0}
h1,h2,h3,h4{font-family:var(--font-display);font-weight:600;line-height:1.16;margin:0;color:var(--ink)}
body::before{content:"";position:fixed;inset:0;z-index:-1;pointer-events:none;background:radial-gradient(880px 460px at 86% -80px,rgba(223,164,94,.20),transparent 62%),radial-gradient(720px 430px at -90px 220px,rgba(210,122,90,.15),transparent 60%),radial-gradient(640px 520px at 108% 58%,rgba(190,200,172,.14),transparent 62%)}
em{font-style:italic;color:var(--accent-dark)}
.post-title em,.FeaturedPost .title em,.header-widget .title em,.error-page .code{color:var(--accent-dark)}
::selection{background:var(--accent);color:#FFF6E8}
:focus-visible{outline:2px solid var(--accent);outline-offset:3px;border-radius:2px}
.widget{margin:0;padding:0}
.section{min-width:0}
.no-items{display:none}
.shell{width:100%;padding-left:clamp(20px,4.5vw,48px);padding-right:clamp(20px,4.5vw,48px)}
.reveal.will-reveal{opacity:0;transform:translateY(24px);transition:opacity .9s var(--ease),transform .9s var(--ease)}
.reveal.in{opacity:1;transform:none}
.skip-link{position:fixed;top:-70px;left:18px;z-index:220;background:var(--ink);color:var(--paper);padding:12px 20px;border-radius:3px;font:600 10.5px/1 var(--font-body);letter-spacing:.22em;text-transform:uppercase;transition:top .35s var(--ease)}
.skip-link:focus{top:14px}
.progress{position:fixed;top:0;left:0;right:0;height:2px;z-index:95;pointer-events:none}
#progressBar{display:block;height:100%;width:0;background:linear-gradient(90deg,var(--accent),var(--accent-dark))}

/* ============ 2. Top bar ============ */
.topbar{position:sticky;top:0;z-index:80;background:rgba(248,240,227,.85);-webkit-backdrop-filter:blur(16px);backdrop-filter:blur(16px);border-bottom:1px solid transparent;transition:border-color .4s ease,background .4s ease,box-shadow .4s ease}
.topbar.is-scrolled{border-bottom-color:var(--line);background:rgba(248,240,227,.95);box-shadow:0 14px 44px -32px rgba(36,22,16,.35)}
.topbar-inner{width:100%;padding:0 clamp(14px,3vw,28px);height:64px;display:flex;align-items:center;gap:14px}
.topbar-title{flex:1 1 auto;min-width:0;text-align:center;font:700 15px/1.25 var(--font-display);letter-spacing:.04em;color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;transition:color .35s var(--ease)}
a.topbar-title:hover{color:var(--accent-dark)}
.touch-icon{width:42px;height:42px;flex:none;border:1px solid transparent;border-radius:50%;display:grid;place-items:center;color:var(--ink);transition:color .3s,border-color .3s,background .3s,transform .3s var(--ease)}
.touch-icon:hover{color:var(--accent-dark);border-color:var(--line);background:var(--surface);transform:translateY(-1px)}
.touch-icon svg{width:21px;height:21px;stroke:currentColor;fill:none;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}

/* ============ 3. Blog header (title + description) ============ */
.blog-head{padding:clamp(46px,7vw,84px) 0 clamp(26px,4vw,44px);text-align:center}
.blog-head .widget{width:100%;padding:0 clamp(20px,4.5vw,48px)}
.header-widget h1,.header-widget .title{font-size:clamp(31px,3.2vw,46px);line-height:1.1;letter-spacing:-.02em;margin:0 0 18px}
.header-widget a.header-title{transition:color .35s var(--ease)}
.header-widget a.header-title:hover{color:var(--accent-dark)}
.header-widget img{max-height:120px;width:auto;margin:0 auto 18px}
.header-widget .description,.header-widget p{margin:0 auto;max-width:62ch;color:var(--muted);font-size:15.5px;line-height:1.9}
.header-widget .description::after{content:"";display:block;width:54px;height:1px;background:var(--accent);margin:26px auto 0}

/* ============ 4. Pages tabs ============ */
#page_list_top{padding-bottom:clamp(26px,4vw,40px)}
.widget.PageList h3.title{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.PageList ul.tabs{display:flex;flex-wrap:wrap;justify-content:center;gap:4px clamp(18px,3vw,34px);list-style:none;margin:0;padding:0 clamp(20px,4.5vw,48px)}
.PageList ul.tabs li{margin:0}
.PageList ul.tabs a{position:relative;display:inline-block;padding:8px 2px;font:600 11px/1 var(--font-body);letter-spacing:.22em;text-transform:uppercase;color:var(--muted);transition:color .35s var(--ease)}
.PageList ul.tabs a::after{content:"";position:absolute;left:0;bottom:2px;width:100%;height:1px;background:var(--accent);transform:scaleX(0);transform-origin:right;transition:transform .45s var(--ease)}
.PageList ul.tabs a:hover{color:var(--ink)}
.PageList ul.tabs a:hover::after{transform:scaleX(1);transform-origin:left}

/* ============ 5. Expanding search ============ */
#search_top{position:fixed;inset:0;z-index:125;display:grid;place-items:center;padding:24px;background:rgba(36,22,16,.45);-webkit-backdrop-filter:blur(3px);backdrop-filter:blur(3px);opacity:0;visibility:hidden;transition:opacity .45s ease,visibility 0s linear .45s}
html.search-open #search_top{opacity:1;visibility:visible;transition:opacity .45s ease}
#search_top .widget{width:min(560px,94vw);border:1px solid var(--line);border-radius:8px;background:var(--surface);padding:18px;box-shadow:0 40px 90px -50px rgba(36,22,16,.55);transform:translateY(14px) scale(.985);transition:transform .5s var(--ease)}html.search-open #search_top .widget{transform:none}
#search_top h3.title{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
#search_top form{display:flex;align-items:center;gap:10px;width:100%;margin-right:auto;border:1px solid var(--line);border-radius:3px;background:var(--paper);padding:4px 6px 4px 18px;transition:border-color .35s,box-shadow .35s}
#search_top form:focus-within{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-soft)}
#search_top input[name=q]{flex:1;min-width:0;border:0;background:transparent;padding:11px 0;font:400 15px/1.4 var(--font-body);color:var(--ink);outline:none}
#search_top input[name=q]::placeholder{color:#A89478}
#search_top .search-submit-container{position:relative;display:grid;place-items:center;width:42px;height:42px;border-radius:2px;background:var(--accent);color:#FFF6E8;cursor:pointer;transition:background .35s}
#search_top .search-submit-container:hover{background:var(--accent-dark)}
#search_top .search-submit-container input[type=submit]{position:absolute;inset:0;opacity:0;cursor:pointer}
#search_top .search-submit-container svg{width:17px;height:17px;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round;pointer-events:none}

/* ============ 6. Featured post (when enabled in Layout) ============ */
.widget.FeaturedPost{width:100%;border:1px solid var(--line);border-radius:6px;background:var(--surface);overflow:hidden;box-shadow:0 26px 60px -48px rgba(36,22,16,.4);padding:0}
.FeaturedPost .widget-content{padding:clamp(22px,3.4vw,34px)}
.FeaturedPost h3.title,.FeaturedPost h2.title{font-size:clamp(23px,3vw,32px);line-height:1.22;letter-spacing:-.015em;margin:0 0 12px}
.FeaturedPost h3.title a,.FeaturedPost h2.title a{transition:color .35s var(--ease)}
.FeaturedPost h3.title a:hover,.FeaturedPost h2.title a:hover{color:var(--accent-dark)}
.FeaturedPost img{width:100%;border-radius:4px;margin-bottom:16px}
.FeaturedPost .snippet{color:var(--muted);font-size:15px;line-height:1.8;margin:0 0 16px}
.featured-card{display:block}
.featured-kicker{display:inline-flex;align-items:center;gap:8px;margin-bottom:12px;font:600 9.5px/1 var(--font-body);letter-spacing:.3em;text-transform:uppercase;color:var(--accent-dark)}
.featured-kicker::before{content:"";width:5px;height:5px;border-radius:50%;background:var(--accent)}
.FeaturedPost .title{font-size:clamp(22px,2vw,29px);line-height:1.2;letter-spacing:-.015em;margin:0 0 12px}
.FeaturedPost .title a{background-image:linear-gradient(currentColor,currentColor);background-size:0% 1px;background-repeat:no-repeat;background-position:0 96%;transition:background-size .55s var(--ease),color .35s var(--ease)}
.FeaturedPost .title a:hover{background-size:100% 1px;color:var(--accent-dark)}

/* ============ 7. Status message ============ */
.status-msg-wrap{margin:0 0 clamp(20px,3vw,30px);padding:14px 20px;border:1px dashed var(--line);border-radius:4px;background:var(--surface);color:var(--muted);font-size:13.5px;line-height:1.7}
.status-msg-wrap a{color:var(--accent-dark);border-bottom:1px solid var(--accent)}

/* ============ 8. Blog posts ============ */
#page_body{padding-bottom:clamp(56px,8vw,96px)}
/* posts feed : compact grid, fixed 3 columns x 2 rows */ .blog-posts{width:100%;display:grid;grid-template-columns:repeat(3,1fr);gap:clamp(14px,1.5vw,22px);padding:0 clamp(20px,4.5vw,48px)}
.blog-posts > *{min-width:0}
.blog-posts .post-outer-container{display:flex}
.blog-posts .post-outer{flex:1 1 auto}
.blog-posts .post .post-footer{margin-top:auto}
.blog-posts h3.post-title{font-size:clamp(20px,1.7vw,25px);line-height:1.28}
@media (max-width:640px){.blog-posts{gap:16px;padding:0 16px}}
.post-outer-container{margin:0}
.post-outer{background:var(--surface);border:1px solid var(--line);border-radius:6px;overflow:hidden;display:flex;flex-direction:column;transition:transform .45s var(--ease),box-shadow .45s var(--ease),border-color .45s var(--ease)}
.post-outer:hover{transform:translateY(-4px);border-color:#E0CFAF;box-shadow:0 28px 60px -44px rgba(36,22,16,.45)}
.snippet-thumbnail-container{display:block;overflow:hidden;background:var(--accent-soft);border-bottom:1px solid var(--line);aspect-ratio:16/8}
.snippet-thumbnail{width:100%;height:100%;display:block;background-size:cover;background-position:center;transition:transform 1.2s var(--ease)}
.post-outer:hover .snippet-thumbnail{transform:scale(1.05)}
.snippet-thumbnail.no-img, .snippet-thumbnail-container.no-img{background:linear-gradient(150deg,var(--accent-soft),var(--surface) 75%)}
.no-img-art{width:100%;height:100%;display:grid;place-items:center;color:var(--accent)}
.no-img-art svg{width:min(220px,52%);height:auto}
.post{padding:clamp(20px,3vw,30px) clamp(20px,3vw,32px) clamp(20px,3vw,26px);display:flex;flex-direction:column;align-items:flex-start;gap:0;flex:1}
.post-title-container{width:100%;min-width:0}
h3.post-title,h1.post-title{overflow-wrap:break-word}
h3.post-title,h1.post-title{font-size:clamp(22px,2.8vw,29px);line-height:1.26;letter-spacing:-.012em;margin:0 0 12px}
.item-view h1.post-title,.page-view h1.post-title{font-size:clamp(27px,2.9vw,40px);line-height:1.14;letter-spacing:-.02em;margin:0 0 18px}
h3.post-title a,h1.post-title a{background-image:linear-gradient(currentColor,currentColor);background-size:0% 1px;background-repeat:no-repeat;background-position:0 97%;transition:background-size .55s var(--ease),color .35s var(--ease)}
h3.post-title a:hover,h1.post-title a:hover{background-size:100% 1px;color:var(--accent-dark)}
.post-header{width:100%}
.post-header-line-1{display:flex;align-items:center;flex-wrap:wrap;gap:8px 14px;font:500 10.5px/1.6 var(--font-body);letter-spacing:.16em;text-transform:uppercase;color:var(--muted)}
.byline{display:inline-flex;align-items:center;gap:8px}
a.timestamp-link{color:var(--muted);transition:color .3s}
a.timestamp-link:hover{color:var(--accent-dark)}
a.comment-link{display:inline-flex;align-items:center;gap:7px;color:var(--muted);transition:color .3s}
a.comment-link:hover{color:var(--accent-dark)}
a.comment-link svg{width:14px;height:14px;stroke:currentColor;fill:none;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.labels-outer-container{width:100%;margin-top:12px}
.labels-container{display:flex;flex-wrap:wrap;gap:7px}
.post-labels a,.labels-items a{display:inline-flex;align-items:center;padding:6px 13px;border:1px solid var(--line);border-radius:999px;font:500 10px/1 var(--font-body);letter-spacing:.12em;text-transform:uppercase;color:var(--muted);transition:all .35s var(--ease)}
.post-labels a:hover,.labels-items a:hover{border-color:var(--accent);color:var(--accent-dark);background:var(--accent-soft);transform:translateY(-2px)}
.post-body-container{width:100%}
.post-snippet{margin:14px 0 4px;color:var(--muted);font-size:15px;line-height:1.8;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
a.jump-link{display:inline-flex;align-items:center;gap:9px;margin-top:16px;font:600 10.5px/1 var(--font-body);letter-spacing:.24em;text-transform:uppercase;color:var(--accent-dark)}
a.jump-link .arr{transition:transform .45s var(--ease)}
a.jump-link::after{content:"";position:absolute}
a.jump-link:hover .arr{transform:translateX(5px)}
.item-post .post-body,.page-body{width:100%;max-width:none;margin-top:26px;font-size:17px;line-height:1.92;color:#2B2721;overflow-wrap:break-word;padding:0 clamp(20px,4.5vw,48px)}
.page-body{margin-top:22px}
.item-post .post-body p,.page-body p{margin:0 0 1.55em}
.item-post .post-body > p:first-of-type::first-letter,.page-body > .post-body > p:first-of-type::first-letter{font-family:var(--font-display);font-weight:600;font-size:3.4em;line-height:.8;float:left;padding:8px 13px 0 0;color:var(--accent-dark)}
.item-post .post-body h2,.item-post .post-body h3,.page-body h2,.page-body h3{margin:2em 0 .7em}
.item-post .post-body h2,.page-body h2{font-size:clamp(24px,3vw,31px)}
.item-post .post-body h3,.page-body h3{font-size:clamp(20px,2.4vw,25px)}
.item-post .post-body a,.page-body a{color:var(--accent-dark);border-bottom:1px solid var(--accent);transition:border-color .3s,background .3s}
.item-post .post-body a:hover,.page-body a:hover{border-bottom-color:transparent;background:var(--accent-soft)}
.item-post .post-body img,.page-body img{border-radius:5px;margin:2.2em auto;border:1px solid var(--line)}
.item-post .post-body ul,.item-post .post-body ol,.page-body ul,.page-body ol{margin:0 0 1.6em;padding-left:1.4em}
.item-post .post-body li,.page-body li{margin-bottom:.5em}
.item-post .post-body li::marker,.page-body li::marker{color:var(--accent)}
.item-post .post-body blockquote,.page-body blockquote{margin:2.4em 0;padding:8px 8px 8px 28px;border-left:2px solid var(--accent);font-family:var(--font-display);font-style:italic;font-size:20px;line-height:1.6}
.item-post .post-body table,.page-body table{width:100%;border-collapse:collapse;margin:2em 0;font-size:14.5px}
.item-post .post-body th,.page-body th{font:600 10.5px/1.4 var(--font-body);letter-spacing:.14em;text-transform:uppercase;color:var(--muted);text-align:left}
.item-post .post-body th,.item-post .post-body td,.page-body th,.page-body td{padding:12px 10px;border-bottom:1px solid var(--line)}
.item-post .post-body pre,.page-body pre{background:#241610;color:#F3E9D8;border-radius:5px;padding:20px 22px;overflow:auto;font-size:13.5px;line-height:1.7}
.item-post .post-body hr,.page-body hr{border:0;height:1px;background:var(--line);margin:3em auto;max-width:120px}

/* ---- share ---- */
.post-footer{width:100%;margin-top:18px;display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap;border-top:1px solid var(--line);padding-top:16px}
.sharing{position:relative;display:inline-flex}
.sharing-button{width:38px;height:38px;border:1px solid var(--line);border-radius:50%;display:grid;place-items:center;color:var(--muted);transition:all .35s var(--ease)}
.sharing-button svg{width:15px;height:15px;stroke:currentColor;fill:none;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.sharing-button:hover{background:var(--ink);border-color:var(--ink);color:var(--paper);transform:translateY(-3px)}
.sharing-popup{position:absolute;left:0;bottom:calc(100% + 10px);z-index:60;min-width:210px;background:var(--surface);border:1px solid var(--line);border-radius:5px;box-shadow:0 26px 60px -30px rgba(36,22,16,.45);padding:10px;opacity:0;visibility:hidden;transform:translateY(8px);transition:all .35s var(--ease)}
.sharing.open .sharing-popup{opacity:1;visibility:visible;transform:none}
.sharing-popup a{display:flex;align-items:center;gap:12px;padding:10px 12px;border-radius:3px;font-size:13.5px;font-weight:500;color:var(--ink);transition:background .25s,color .25s}
.sharing-popup a:hover{background:var(--accent-soft);color:var(--accent-dark)}
.sharing-popup svg{width:16px;height:16px;stroke:currentColor;fill:none;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}

/* ---- pager ---- */
#blog-pager{width:100%;margin:clamp(30px,4.5vw,46px) 0 0;padding:0 clamp(20px,4.5vw,48px);display:flex;justify-content:center;gap:14px;flex-wrap:wrap}
.blog-pager a{display:inline-flex;align-items:center;gap:10px;padding:14px 30px;border:1px solid var(--ink);border-radius:2px;font:600 11px/1 var(--font-body);letter-spacing:.24em;text-transform:uppercase;color:var(--ink);background:transparent;transition:all .4s var(--ease)}
.blog-pager a:hover{background:var(--ink);color:var(--paper);transform:translateY(-2px);box-shadow:0 16px 34px -18px rgba(36,22,16,.5)}
.blog-pager svg{width:15px;height:15px;stroke:currentColor;fill:none;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}

/* ---- empty state ---- */
.no-posts{width:100%;margin:0 auto;padding:clamp(48px,7vw,80px) clamp(20px,4.5vw,48px);text-align:center;border:1px dashed var(--line);border-radius:6px;background:var(--surface)}
.no-posts h3{font-size:clamp(21px,2.8vw,27px);letter-spacing:-.01em}
.no-posts p{color:var(--muted);font-size:14.5px;margin:12px 0 24px}

/* ============ 9. Drawer sidebar (Archive / Labels / Report abuse) ============ */
.scrim{position:fixed;inset:0;z-index:110;background:rgba(36,22,16,.45);opacity:0;visibility:hidden;transition:opacity .45s ease,visibility 0s linear .45s;-webkit-backdrop-filter:blur(2px);backdrop-filter:blur(2px)}
html.drawer-open .scrim{opacity:1;visibility:visible;transition:opacity .45s ease}
.sidebar-container{position:fixed;top:0;right:0;bottom:0;z-index:120;width:min(370px,90vw);background:var(--paper);border-left:1px solid var(--line);box-shadow:-40px 0 90px -50px rgba(36,22,16,.5);transform:translateX(105%);transition:transform .55s var(--ease);overflow-y:auto;overscroll-behavior:contain;padding:18px 24px 40px}
html.drawer-open .sidebar-container{transform:none}
.sidebar-back{margin-left:auto;display:grid}
.sidebar-container .widget{margin-bottom:16px;border:1px solid var(--line);border-radius:5px;background:var(--surface);padding:4px 18px}
.sidebar-container details.collapsible > summary{list-style:none;cursor:pointer;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 0}
.sidebar-container details.collapsible > summary::-webkit-details-marker{display:none}
.sidebar-container .collapsible-title{display:flex;align-items:center;flex:1}
.sidebar-container .collapsible-title h3.title{margin:0;font:600 10.5px/1 var(--font-body) !important;letter-spacing:.28em;text-transform:uppercase;color:var(--ink)}
.sidebar-container .chevron-down,.sidebar-container .chevron-up{width:16px;height:16px;stroke:var(--accent);fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;transition:transform .4s var(--ease)}
.sidebar-container .chevron-up{display:none}
.sidebar-container details[open] .chevron-down{display:none}
.sidebar-container details[open] .chevron-up{display:block}
.sidebar-container .widget-content{padding:0 0 14px}
.sidebar-container details[open].collapsible > .widget-content{animation:drawerIn .5s var(--ease)}
@keyframes drawerIn{from{opacity:0;transform:translateY(-6px)}to{opacity:1;transform:none}}

/* archive list */
#ArchiveList ul{list-style:none;margin:0;padding:0}
#ArchiveList ul ul{padding-left:14px}
#ArchiveList .hierarchy-title{margin:0}
#ArchiveList a{display:inline-flex;align-items:center;gap:8px;padding:6px 0;font-size:13.5px;color:var(--ink);transition:color .3s}
#ArchiveList a:hover{color:var(--accent-dark)}
#ArchiveList .zippy{color:var(--accent);font-size:10px}
#ArchiveList .post-count{font:600 10px/1 var(--font-body);letter-spacing:.06em;color:var(--accent-dark);background:var(--accent-soft);border-radius:999px;padding:3px 8px}
#ArchiveList ul.posts a{font-size:13px;color:var(--muted);padding:4px 0}
#ArchiveList ul.posts a:hover{color:var(--accent-dark)}

/* labels list */
.list-label-widget-content ul,.cloud-label-widget-content{list-style:none;margin:0;padding:0;display:flex;flex-direction:column}
.list-label-widget-content li{border-bottom:1px solid var(--line)}
.list-label-widget-content li:last-child{border-bottom:0}
a.label-name{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 2px;font-size:13.5px;color:var(--ink);transform:translateX(0);transition:color .3s,transform .35s var(--ease)}
a.label-name::after{content:"\2192";opacity:0;transform:translateX(-6px);transition:opacity .3s,transform .3s var(--ease);color:var(--accent)}
a.label-name:hover{color:var(--accent-dark);transform:translateX(4px)}
a.label-name:hover::after{opacity:1;transform:none}

/* report abuse */
.popular-list{list-style:none;margin:0;padding:0}
.popular-list li{display:flex;gap:14px;align-items:baseline;border-bottom:1px solid var(--line);padding:9px 0}
.popular-list li:last-child{border-bottom:0}
.popular-num{font:italic 600 19px/1 var(--font-display);color:var(--accent);min-width:22px}
.popular-list a{font-size:13.5px;line-height:1.6;color:var(--ink);transition:color .3s}
.popular-list a:hover{color:var(--accent-dark)}
.widget.ReportAbuse{padding:16px 18px}
.widget.ReportAbuse h3.title{margin:0;font:600 10.5px/1 var(--font-body) !important;letter-spacing:.28em;text-transform:uppercase}
a.report_abuse{color:var(--muted);transition:color .3s}
a.report_abuse:hover{color:var(--accent-dark)}

/* ============ 10. Comments ============ */
#comments{width:100%;margin:clamp(34px,5vw,52px) 0 0;padding:0 clamp(20px,4.5vw,48px);border-top:1px solid var(--line);padding-top:clamp(28px,4vw,40px)}
#comments h3.title,#comments h3,#comments h4{font-size:22px;letter-spacing:-.01em;margin:0 0 20px}
#comments h4#comment-post-message{font-size:19px;margin:22px 0 12px}
#comments .comment-form{background:var(--surface);border:1px solid var(--line);border-radius:5px;padding:18px}
#comments iframe{width:100%;border:0;color-scheme:light}
#comments .comment-thread ol{list-style:none;margin:0;padding:0}
#comments .comment-thread ol ol{padding-left:30px;border-left:1px solid var(--line);margin:16px 0 0}
#comments .comment{margin:0 0 22px}
#comments .comment-block{background:var(--surface);border:1px solid var(--line);border-radius:5px;padding:18px 20px}
#comments .comment-header{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:8px}
#comments .user{font:600 15px/1.3 var(--font-display);font-style:normal}
#comments .datetime a{font:500 10px/1 var(--font-body);letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}
#comments .avatar-image-container{width:36px;height:36px;border-radius:50%;overflow:hidden;border:1px solid var(--accent);background:var(--accent-soft);flex:none}
#comments .avatar-image-container img{width:100%;height:100%;object-fit:cover}
#comments .comment-content{color:#2B2721;line-height:1.75;overflow-wrap:break-word}
#comments .comment-actions a,#comments .continue a{display:inline-block;margin-right:14px;font:600 9.5px/1 var(--font-body);letter-spacing:.22em;text-transform:uppercase;color:var(--accent-dark)}

/* ============ 11. Error page ============ */
.error-page{width:100%;padding:clamp(60px,9vw,110px) clamp(20px,4.5vw,48px);text-align:center}
.error-page .code{font:italic 600 clamp(70px,12vw,120px)/1 var(--font-display);color:var(--accent);opacity:.55}
.error-page h3{font-size:clamp(24px,3.4vw,34px);letter-spacing:-.015em;margin:18px 0 12px}
.error-page p{color:var(--muted);margin:0 0 30px}

/* ============ 12. Footer / attribution ============ */
.site-footer{background:var(--footer-bg);margin-top:clamp(30px,5vw,60px)}
#footer .widget{width:100%;padding:30px clamp(20px,4.5vw,48px);text-align:center}
.widget.Attribution .widget-content{color:#9A8468;font-size:12.5px;opacity:1}
.widget.Attribution .blogger a{display:inline-flex;align-items:center;gap:10px;color:#D9A05B;transition:color .3s}
.widget.Attribution .blogger a:hover{color:#F0C084}
.widget.Attribution svg{width:17px;height:17px;fill:currentColor}

/* ============ 13. Responsive ============ */
@media (max-width:640px){
 .topbar-title{font-size:13.5px}
 .blog-head .widget{padding-top:2px}
 .post-outer:hover{transform:none}
 .blog-posts{gap:20px}
 .sharing-popup{left:auto;right:0}
}


/* ---- popup copy-link button ---- */
.sharing-popup button.copy-link{display:flex;align-items:center;gap:12px;width:100%;padding:10px 12px;border-radius:3px;font:500 13.5px/1.4 var(--font-body);color:var(--ink);text-align:left;transition:background .25s,color .25s}
.sharing-popup button.copy-link:hover{background:var(--accent-soft);color:var(--accent-dark)}
.sharing-popup button.copy-link svg{width:16px;height:16px;stroke:currentColor;fill:none;stroke-width:1.7;stroke-linecap:round}
.blog-pager .arr{display:inline-block;transition:transform .4s var(--ease)}
.blog-pager a:hover .arr{transform:translateX(4px)}
.vertical-ad-container:empty{display:none}

/* ============ 14. Motion / print ============ */
@media (prefers-reduced-motion:reduce){
 *,*::before,*::after{animation-duration:.01ms !important;animation-iteration-count:1 !important;transition-duration:.01ms !important;scroll-behavior:auto !important}
 .reveal{opacity:1 !important;transform:none !important}
 .sidebar-container{transition:none}
}
@media print{
 .topbar,.sidebar-container,.scrim,#search_top,.sharing,.blog-pager,#comments{display:none !important}
}

/* ===== footer link directory ===== */
.footer-dir{width:100%;padding:clamp(30px,4vw,54px) clamp(20px,4.5vw,48px) 12px;display:grid;grid-template-columns:1.4fr 1fr 1.5fr 1.1fr;gap:clamp(22px,3.5vw,44px);text-align:left}
@media (max-width:980px){.footer-dir{grid-template-columns:1fr 1fr}}
@media (max-width:560px){.footer-dir{grid-template-columns:1fr}}
.fd-col b{display:block;font:600 11px/1 var(--font-body);letter-spacing:.26em;text-transform:uppercase;color:#D9A05B;margin-bottom:14px}
.fd-col p{margin:0 0 10px;color:#BCAC94;font-size:13px;line-height:1.75}
.fd-col a{display:block;padding:3px 0;color:#D8C7AE;font-size:13px;line-height:2.05;text-decoration:none;background:linear-gradient(#F0C084,#F0C084) no-repeat 0 100%/0 1px;transition:color .3s,background-size .35s var(--ease)}
.fd-col a:hover{color:#F0C084;background-size:100% 1px}
.fd-rooms{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}
.fd-soc{display:flex;gap:10px;margin-top:4px}
.fd-soc a{width:38px;height:38px;border:1px solid #3A2A1C;border-radius:50%;display:grid;place-items:center;color:#D9A05B;background:none;line-height:1;transition:.3s var(--ease)}
.fd-soc a:hover{border-color:#D9A05B;transform:translateY(-3px);background:none;background-size:0}
.fd-soc svg{width:16px;height:16px;stroke:currentColor;fill:none;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
/* attribution kept for Blogger compliance — solid, never transparent */
.widget.Attribution .widget-content{color:#9A8468;font-size:12.5px;opacity:1}
/* ===== ambient glyphs + kicker draw + scroll-top ===== */
.body-glyphs{position:fixed;inset:0;z-index:0;pointer-events:none;overflow:hidden}
.body-glyphs span{position:absolute;font:italic 600 clamp(30px,4vw,54px)/1 var(--font-display);color:rgba(169,78,38,.06);animation:bgFloat 11s ease-in-out infinite}
.body-glyphs span:nth-child(2){animation-delay:-2.5s}.body-glyphs span:nth-child(3){animation-delay:-5s}.body-glyphs span:nth-child(4){animation-delay:-7.5s}.body-glyphs span:nth-child(5){animation-delay:-9s}
@keyframes bgFloat{0%,100%{transform:translateY(0) rotate(-5deg)}50%{transform:translateY(-26px) rotate(6deg)}}
@media (prefers-reduced-motion:reduce){.body-glyphs{display:none}}
.reveal.in .featured-kicker::before{animation:fkRule .8s var(--ease) .2s backwards}
@keyframes fkRule{from{transform:scaleX(0)}to{transform:scaleX(1)}}
#toTop{position:static;width:50px;height:50px;border-radius:50%;background:var(--surface);border:1px solid var(--line);display:grid;place-items:center;box-shadow:0 16px 38px -20px rgba(36,22,16,.5);opacity:0;pointer-events:none;transform:translateY(12px);transition:.4s var(--ease)}
#toTop.show{opacity:1;pointer-events:auto;transform:none}
#toTop:hover{transform:translateY(-3px)}

/* ============ 4b. Floating action stack : search / sidebar / back-to-top (right edge, vertically centred) ============ */
.fab-stack{position:fixed;right:clamp(12px,2.2vw,24px);top:50%;transform:translateY(-50%);z-index:95;display:flex;flex-direction:column;gap:12px;align-items:center}
.fab,.fab-stack #toTop{width:50px;height:50px;border-radius:50%;background:var(--surface);border:1px solid var(--line);display:grid;place-items:center;box-shadow:0 16px 38px -20px rgba(36,22,16,.5);cursor:pointer;padding:0}
.fab{transition:transform .35s var(--ease),border-color .35s,background .35s}
.fab svg{width:19px;height:19px;stroke:var(--accent-dark);fill:none;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}
.fab:hover{transform:translateY(-3px);border-color:var(--copper)}
.fab:active{transform:translateY(-1px) scale(.97)}
.fab-divider{width:26px;height:1px;background:var(--line);flex:none}
a.fab{color:inherit;text-decoration:none}
.fab:focus-visible{outline:2px solid var(--accent);outline-offset:2px}
#fkToast{position:fixed;left:50%;bottom:28px;transform:translate(-50%,16px);z-index:200;background:var(--ink);color:#F8F0E3;font:500 13px/1.3 var(--font-body);padding:11px 18px;border-radius:999px;opacity:0;pointer-events:none;transition:opacity .35s ease,transform .35s ease}
#fkToast.on{opacity:1;transform:translate(-50%,0)}
@media (max-width:560px){.fab-divider{width:22px}}
@media (max-width:560px){.fab,.fab-stack #toTop{width:44px;height:44px}.fab svg{width:17px;height:17px}}


#toTop .ta{width:15px;height:15px;stroke:var(--accent-dark);fill:none;stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round}
@media print{.fab-stack,#fkToast,.body-glyphs{display:none!important}}

/* ══════════════ FEED · shared base ══════════════ */
.blog-posts{width:100%;display:grid;grid-auto-flow:row;padding:0 clamp(20px,4.5vw,48px)}
.blog-posts > *{min-width:0}
.blog-posts .post-outer-container{display:flex}
.blog-posts .post-outer{flex:1 1 auto;width:100%;background:var(--surface);border:1px solid var(--line);border-radius:8px;overflow:hidden;display:flex;flex-direction:column;transition:transform .45s var(--ease),box-shadow .45s var(--ease),border-color .45s var(--ease)}
.blog-posts .post-outer:hover{transform:translateY(-4px);border-color:#E0CFAF;box-shadow:0 28px 60px -44px rgba(36,22,16,.45)}
.blog-posts .snippet-thumbnail-container{display:block;overflow:hidden;background:var(--accent-soft);aspect-ratio:16/8}
.blog-posts .snippet-thumbnail{display:block;width:100%;height:100%;background-size:cover;background-position:center}
.blog-posts .snippet-thumbnail img{width:100%;height:100%;object-fit:cover;display:block}
.blog-posts .no-img-art svg{width:min(220px,50%)}
.blog-posts .post{padding:clamp(18px,2.6vw,28px) clamp(18px,2.6vw,30px);display:flex;flex-direction:column;align-items:flex-start;flex:1}
.blog-posts .post-title-container{width:100%;min-width:0}
.blog-posts h3.post-title{overflow-wrap:break-word}
.blog-posts .post-header{width:100%}
.blog-posts .post-header-line-1{display:flex;align-items:center;flex-wrap:wrap;gap:8px 12px;font:500 10.5px/1 var(--font-body);letter-spacing:.16em;text-transform:uppercase;color:var(--muted)}
.blog-posts .post-timestamp{white-space:nowrap}
.blog-posts .labels-outer-container{margin-top:12px}
.blog-posts .labels-container{display:flex;flex-wrap:wrap;gap:5px}
.blog-posts .post-labels a{display:inline-block;padding:5px 12px;border:1px solid var(--line);border-radius:999px;font:500 9.5px/1 var(--font-body);letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
.blog-posts .post-body-container{width:100%}
.blog-posts .post-snippet{margin:12px 0 0;color:var(--muted);font-size:15px;line-height:1.75;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.blog-posts a.jump-link{display:inline-flex;align-items:center;gap:9px;margin-top:16px;font:600 10.5px/1 var(--font-body);letter-spacing:.22em;text-transform:uppercase;color:var(--accent-dark)}
.blog-posts .post-footer{display:flex;width:100%;margin-top:16px;padding-top:12px;border-top:1px solid var(--line)}

/* ══════════════ FEED · HOMEPAGE : all recent articles, 3 columns, compact cards ══════════════ */
.fk-home .blog-posts{grid-template-columns:repeat(3,minmax(0,1fr));gap:clamp(14px,1.6vw,22px)}
.fk-home .snippet-thumbnail-container{aspect-ratio:16/10}
.fk-home .snippet-thumbnail img{filter:sepia(.16) saturate(.92) hue-rotate(-8deg)}
.fk-home .post{padding:14px 16px 13px}
.fk-home h3.post-title{font-size:clamp(14.5px,1.05vw,17.5px);line-height:1.35;margin:0 0 8px;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
.fk-home .post-header-line-1{font-size:9.5px;gap:8px}
.fk-home .labels-outer-container{margin-top:8px;max-height:22px;overflow:hidden}
.fk-home .labels-container{flex-wrap:nowrap;overflow:hidden}
.fk-home .post-labels a{padding:4px 10px;font-size:8.5px;white-space:nowrap}
.fk-home .post-snippet{margin:9px 0 0;font-size:12.5px;line-height:1.55;-webkit-line-clamp:2}
.fk-home a.jump-link{margin-top:11px;font-size:9.5px}
.fk-home .post-footer{display:none}
@media (max-width:540px){
.fk-home .blog-posts{grid-template-columns:minmax(0,1fr);gap:14px;padding:0 16px}
.fk-home h3.post-title{font-size:16px}
.fk-home .post-snippet{font-size:13px}
}

/* ══════════════ FEED · READ-MORE PAGES : the big default look, 10 articles, freestyle ══════════════ */
.fk-rest .blog-posts{grid-template-columns:minmax(0,1fr);gap:clamp(22px,3vw,34px)}
/* ══════════════ WIDTH SYSTEM · rebuilt clean : 100% everywhere, nothing pasted can box it ══════════════ */
html,body{width:100%;max-width:100%;margin:0;overflow-x:clip}
.item-post,.post-outer-container,.blog-posts,main,article{max-width:none;margin-left:0;margin-right:0}
.item-post .post-body,.page-body{width:100%;max-width:none;font-size:17px;line-height:1.92;color:#2B2721;overflow-wrap:break-word;padding:0 clamp(20px,4.5vw,48px)}
.item-post .post-body > *,.page-body > *{width:100%!important;max-width:none!important;float:none!important;margin-left:0!important;margin-right:0!important}
.item-post .post-body div,.item-post .post-body section,.item-post .post-body article,.page-body div,.page-body section,.page-body article{width:auto!important;max-width:none!important;float:none!important}
.item-post .post-body *,.page-body *{min-width:0!important}
.item-post .post-body img,.page-body img,.item-post .post-body iframe,.page-body iframe,.item-post .post-body video,.page-body video,.item-post .post-body table,.page-body table,.item-post .post-body pre,.page-body pre{max-width:100%!important;margin-left:auto!important;margin-right:auto!important}
.item-post .post-body hr,.page-body hr{max-width:120px!important}
.item-post .post-body table,.page-body table{display:block;overflow-x:auto;-webkit-overflow-scrolling:touch}
@media (max-width:760px){
.item-post .post-body [style*='display:grid'],.page-body [style*='display:grid'],
.item-post .post-body div[class*='grid'],.page-body div[class*='grid'],
.item-post .post-body div[class*='stat'],.page-body div[class*='stat'],
.item-post .post-body div[class*='strip'],.page-body div[class*='strip'],
.item-post .post-body div[class*='cards'],.page-body div[class*='cards'],
.item-post .post-body div[class*='cols'],.page-body div[class*='cols'],
.item-post .post-body div[class*='steps'],.page-body div[class*='steps']{grid-template-columns:minmax(0,1fr)!important;gap:12px!important}
.item-post .post-body [style*='display:flex'],.page-body [style*='display:flex'],
.item-post .post-body div[class*='row'],.page-body div[class*='row']{flex-wrap:wrap!important}
.item-post .post-body pre,.page-body pre{white-space:pre-wrap}
}


/* ══════════════ KV HERO · fresh build (rotating word + 20-slide money-maths card) ══════════════ */
:root{--font-script:"Caveat",cursive}
.header-widget{display:none!important}
.kv-hero{position:relative;width:100%;padding:clamp(38px,6vw,72px) clamp(20px,4.5vw,48px) clamp(28px,4vw,46px);overflow:hidden;background:linear-gradient(180deg,#FDF7EA 0%,var(--paper) 78%)}
.kv-hero::before,.kv-hero::after{content:"";position:absolute;border-radius:50%;filter:blur(60px);opacity:.5;pointer-events:none}
.kv-hero::before{width:420px;height:420px;right:-120px;top:-140px;background:radial-gradient(circle,#F5D9A8 0%,transparent 70%)}
.kv-hero::after{width:380px;height:380px;left:-140px;bottom:-160px;background:radial-gradient(circle,#DCE3C8 0%,transparent 70%)}
.kv-hero-in{position:relative;z-index:1;display:grid;grid-template-columns:minmax(0,1.08fr) minmax(0,.92fr);gap:clamp(24px,4vw,54px);align-items:center}
.kv-badge{display:inline-flex;align-items:center;gap:9px;padding:9px 18px;border-radius:999px;background:rgba(255,251,242,.8);border:1px solid var(--line);color:var(--muted);font:700 10px/1 var(--font-body);letter-spacing:.26em;text-transform:uppercase;animation:kvUp .7s var(--ease) .05s both}
.kv-badge i{width:7px;height:7px;border-radius:50%;background:var(--grad);flex:none;animation:kvPulse 2.4s ease infinite}
@keyframes kvPulse{0%,100%{box-shadow:0 0 0 0 rgba(201,123,61,.45)}55%{box-shadow:0 0 0 7px rgba(201,123,61,0)}}
.kv-head{margin:20px 0 16px;font:600 clamp(34px,4.4vw,60px)/1.08 var(--font-display);letter-spacing:-.02em;color:var(--ink);animation:kvUp .7s var(--ease) .12s both}
.kv-flip{display:inline-grid;vertical-align:bottom;overflow:hidden;text-align:left}
.kv-word{grid-area:1/1;white-space:nowrap;color:var(--accent-dark);opacity:0;transform:translateY(75%);transition:opacity .5s ease,transform .62s cubic-bezier(.19,1,.22,1)}
.kv-word.on{opacity:1;transform:none}
.kv-word.out{opacity:0;transform:translateY(-75%)}
.kv-lede{max-width:56ch;margin:0 0 24px;font:400 clamp(15px,1.4vw,16.5px)/1.75 var(--font-body);color:var(--muted);animation:kvUp .7s var(--ease) .3s both}
.kv-lede strong{color:var(--ink);font-weight:600}
.kv-search{display:flex;align-items:center;gap:8px;max-width:520px;padding:6px 6px 6px 18px;background:var(--surface);border:1px solid var(--line);border-radius:999px;box-shadow:0 18px 44px -30px rgba(36,22,16,.35);transition:border-color .3s,box-shadow .3s;animation:kvUp .7s var(--ease) .42s both}
.kv-search:focus-within{border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-soft)}
.kv-search svg{width:17px;height:17px;stroke:var(--muted);fill:none;stroke-width:1.8;stroke-linecap:round;flex:none}
.kv-search input{flex:1;min-width:0;border:0;background:transparent;padding:10px 0;font:400 15px/1.4 var(--font-body);color:var(--ink);outline:none}
.kv-search input::placeholder{color:#A89478}
.kv-search button{flex:none;padding:11px 22px;border:0;border-radius:999px;background:var(--accent);color:#FFF6E8;font:600 13.5px/1 var(--font-body);cursor:pointer;transition:background .3s}
.kv-search button:hover{background:var(--accent-dark)}
.kv-btns{display:flex;flex-wrap:wrap;gap:12px;margin-top:18px;animation:kvUp .7s var(--ease) .54s both}
.kv-btn{display:inline-flex;align-items:center;gap:9px;padding:13px 24px;border-radius:999px;font:600 13.5px/1 var(--font-body);text-decoration:none;cursor:pointer;border:1px solid transparent;transition:transform .3s,box-shadow .3s,background .3s}
.kv-btn .ar{transition:transform .35s var(--ease)}
.kv-btn:hover .ar{transform:translate(3px,-3px)}
.kv-btn.dark{background:var(--ink);color:#F8F0E3}
.kv-btn.dark:hover{transform:translateY(-2px);box-shadow:0 18px 40px -22px rgba(36,22,16,.55)}
.kv-btn.light{background:var(--surface);color:var(--ink);border-color:var(--line)}
.kv-btn.light:hover{transform:translateY(-2px);border-color:#E0CFAF}
.kv-trust{display:flex;flex-wrap:wrap;gap:10px 22px;margin-top:20px;animation:kvUp .7s var(--ease) .66s both}
.kv-trust span{display:inline-flex;align-items:center;gap:8px;font:500 12.5px/1 var(--font-body);color:var(--muted)}
.kv-trust svg{width:14px;height:14px;stroke:var(--accent-dark);fill:none;stroke-width:2.2;stroke-linecap:round;stroke-linejoin:round;flex:none}
@keyframes kvUp{from{opacity:0;transform:translateY(18px)}to{opacity:1;transform:none}}
.kv-cardwrap{position:relative;z-index:1;display:flex;justify-content:center;animation:kvUp .9s var(--ease) .35s both}
.kv-card{position:relative;width:min(440px,100%);background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:22px 26px 14px;box-shadow:0 34px 80px -46px rgba(36,22,16,.5);transform:rotate(-1.6deg)}
.kv-card::before{content:"";position:absolute;top:-13px;left:50%;width:96px;height:24px;transform:translateX(-50%) rotate(2.5deg);background:rgba(229,187,116,.55);border-left:1px dashed rgba(36,22,16,.15);border-right:1px dashed rgba(36,22,16,.15)}
.kv-card::after{content:"";position:absolute;inset:9px;border:1px dashed var(--line);border-radius:10px;pointer-events:none}
.kv-stage{overflow:hidden;position:relative;z-index:1}
.kv-track{display:flex;transition:transform .65s cubic-bezier(.22,.61,.36,1)}
.kv-pane{flex:0 0 100%;min-width:0;padding:2px 2px 4px}
.kv-q{margin:2px 0 10px;font:600 21px/1.25 var(--font-script);color:var(--accent-dark)}
.kv-row{display:flex;justify-content:space-between;align-items:baseline;gap:14px;padding:8px 2px;border-bottom:1px solid var(--line);font:400 14px/1.4 var(--font-body);color:var(--ink)}
.kv-row b{font:600 15px/1 var(--font-body);white-space:nowrap}
.kv-row b.neg{color:#A03A22}
.kv-row.total{border-bottom:0;padding-top:10px;font-weight:600}
.kv-row.total b{font:700 18px/1 var(--font-display);color:var(--accent-dark)}
.kv-row.total.neg b{color:#A03A22}
.kv-note{margin:8px 0 0;font:400 10.5px/1.5 var(--font-body);color:#A89478}
.kv-work{margin:10px 0 0;font:600 15px/1 var(--font-script);color:var(--muted);text-align:center;border-top:1px dashed var(--line);padding-top:10px}
@media (max-width:540px){
.kv-hero{padding:24px 14px 20px}
.kv-hero-in{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:13px}
.kv-badge{font-size:8px;padding:7px 12px;letter-spacing:.18em}
.kv-head{font-size:clamp(21px,6.2vw,31px);margin:12px 0 10px}
.kv-lede{font-size:12px;line-height:1.6;margin-bottom:13px}
.kv-search{padding:4px 4px 4px 12px;max-width:none}
.kv-search input{font-size:12px;padding:8px 0}
.kv-search button{padding:9px 13px;font-size:11.5px}
.kv-btns{gap:8px;margin-top:12px}
.kv-btn{padding:10px 13px;font-size:11.5px}
.kv-trust{gap:6px 13px;margin-top:12px}
.kv-trust span{font-size:10px}
.kv-card{padding:14px 13px 10px}
.kv-q{font-size:14.5px;margin-bottom:7px}
.kv-row{font-size:11.5px;padding:6px 2px;gap:9px}
.kv-row b{font-size:12px}
.kv-row.total b{font-size:14.5px}
.kv-note{font-size:8.5px}
.kv-work{font-size:12.5px}
}
@media (prefers-reduced-motion:reduce){
.kv-badge i{animation:none}
.kv-word{transition:opacity .2s ease;transform:none}
.kv-word.out{transform:none}
.kv-track{transition:none}
.kv-badge,.kv-head,.kv-lede,.kv-search,.kv-btns,.kv-trust,.kv-cardwrap{animation:none}
}

/* — kv v2 creative additions (homepage-only, kv-scoped) — */
.fk-home .kv-hero{cursor:default}
.fk-home .kv-hero::before,.fk-home .kv-hero::after{animation:kvDrift 16s ease-in-out infinite alternate}
@keyframes kvDrift{from{transform:translate(0,0) scale(1)}to{transform:translate(-46px,26px) scale(1.08)}}
.kv-glyphs{position:absolute;inset:0;pointer-events:none;z-index:0}
.kv-glyphs span{position:absolute;font:600 64px/1 var(--font-display);color:var(--accent);opacity:.13;animation:kvFloat 7s ease-in-out infinite alternate}
.kv-glyphs span:nth-child(1){left:4%;top:18%;font-size:76px;animation-delay:0s}
.kv-glyphs span:nth-child(2){right:7%;top:9%;font-size:56px;animation-delay:1.2s}
.kv-glyphs span:nth-child(3){left:44%;top:64%;font-size:48px;animation-delay:2.1s}
.kv-glyphs span:nth-child(4){left:9%;bottom:12%;font-size:58px;animation-delay:2.8s}
.kv-glyphs span:nth-child(5){right:26%;bottom:5%;font-size:66px;animation-delay:3.6s}
@keyframes kvFloat{from{transform:translateY(-9px) rotate(-4deg)}to{transform:translateY(11px) rotate(5deg)}}
.kv-squig{display:block;width:min(210px,46vw);height:13px;margin:4px 0 0 3px;overflow:visible}
.kv-squig path{fill:none;stroke:var(--accent);stroke-width:3.4;stroke-linecap:round;stroke-dasharray:170;stroke-dashoffset:170;animation:kvDraw 1s ease-out .95s forwards}
@keyframes kvDraw{to{stroke-dashoffset:0}}
.kv-progress{height:3px;border-radius:99px;background:var(--line);overflow:hidden;margin:12px 0 0}
.kv-progress i{display:block;height:100%;width:0;border-radius:99px;background:var(--accent)}
.kv-card{transition:transform .55s var(--ease)}
.fk-home .kv-card:hover{transform:rotate(-.4deg) translateY(-5px)}
@media (max-width:540px){
.kv-glyphs span{font-size:34px;opacity:.1}
}
@media (prefers-reduced-motion:reduce){
.kv-squig path{stroke-dashoffset:0}
}
/* — kv v3 · playground, greeting, magnet, parallax, share, absolute home-only guarantee — */
.kv-ul{background:linear-gradient(transparent 80%,var(--accent-soft) 0)}
@media (max-width:540px){
}

