@media (max-width:760px){
.fab-stack{gap:5px}
}
@media (max-width:540px){
.kv-hero{padding-top:clamp(20px,5vw,30px)}
.kv-card{width:min(100%,352px);margin-inline:auto;transform:none;padding:16px 15px 11px}
.kv-stage{width:100%}
.kv-pane{flex:0 0 100%;width:100%}
.kv-row{font-size:11px;padding:6px 0;gap:8px}
.kv-row b{font-size:11.5px;white-space:normal;text-align:right}
.kv-q{font-size:14px}
.kv-note{font-size:9.5px;line-height:1.45}
