}

/* — static-page dedupe guards: pages carry their own heroes; never double title or chrome — */
.page-type-static_page .post-title-container{display:none!important}
#page_body .topbar,#page_body .blog-head,#page_body .page-list,#page_body #search_top,#page_body .fab-stack,#page_body .site-footer,#page_body .skip-link,#page_body .progress,#page_body .scrim,#page_body .sidebar-container,#page_body .body-glyphs,#page_body #fkToast,#page_body #toTop,#page_body footer.post-footer{display:none!important}





/* ═══ NAV · warm terracotta tabs — theme-native colours ═══ */
@keyframes navRise{from{opacity:0;transform:translateY(-8px)}to{opacity:1;transform:none}}
@keyframes squigDraw{from{stroke-dashoffset:120}to{stroke-dashoffset:0}}
.topbar-title{display:inline-flex;flex-direction:row;align-items:center;justify-content:center;gap:10px;font:800 clamp(20px,3vw,30px)/1.1 var(--font-display);letter-spacing:.1em;padding:4px 0 10px;white-space:nowrap}
.topbar-title .tb-a{color:var(--ink)}
.topbar-title .tb-b{color:var(--accent);transition:color .4s var(--ease)}
.topbar-title:hover .tb-b{color:var(--accent-dark)}
.tb-squig{position:absolute;left:50%;transform:translateX(-50%);bottom:-6px;width:clamp(80px,9vw,112px);height:8px;overflow:visible}
.tb-squig path{fill:none;stroke:var(--accent);stroke-width:2.4;stroke-linecap:round;stroke-dasharray:120;stroke-dashoffset:120;animation:squigDraw .9s ease-out .35s forwards}
.tabs{display:flex;flex-wrap:wrap;justify-content:center;gap:9px;padding:14px clamp(14px,3.5vw,48px) 20px}
.tabs li{margin:0;animation:navRise .5s var(--ease) both}
.tabs li:nth-child(1){animation-delay:.04s}.tabs li:nth-child(2){animation-delay:.08s}
.tabs li:nth-child(3){animation-delay:.12s}.tabs li:nth-child(4){animation-delay:.16s}
.tabs li:nth-child(5){animation-delay:.2s}.tabs li:nth-child(6){animation-delay:.24s}
.tabs li:nth-child(7){animation-delay:.28s}.tabs li:nth-child(8){animation-delay:.32s}
.tabs li:nth-child(n+9){animation-delay:.36s}
.tabs a{display:inline-flex;align-items:center;gap:8px;padding:9px 17px;border:1px solid rgba(156,69,34,.24);border-radius:999px;background:#F9F0DF;color:#8A5B3C;font:700 11px/1 var(--font-body);letter-spacing:.16em;transition:transform .35s var(--ease),background .35s,color .35s,border-color .35s,box-shadow .35s}
.tabs a::after{display:none}
.tabs a::before{display:none}
.tabs a:hover{transform:translateY(-2px);border-color:var(--accent);background:#FFFDF8;color:var(--accent-dark);box-shadow:0 12px 24px -18px rgba(156,69,34,.6)}
.tabs li.selected a{background:var(--accent-dark);border-color:var(--accent-dark);color:#FFF6E8}
.tabs li.selected a:hover{transform:none}
@media (max-width:560px){
.topbar-title{font-size:16.5px;letter-spacing:.08em}
.tabs{flex-wrap:nowrap;overflow-x:auto;justify-content:flex-start;scrollbar-width:none;padding:10px 14px 14px;gap:7px}
.tabs::-webkit-scrollbar{display:none}
.tabs a{font-size:10.5px;padding:9px 14px;white-space:nowrap}
}
@media (prefers-reduced-motion:reduce){.tabs li{animation:none}.tb-squig path{animation:none;stroke-dashoffset:0}}

/* ═══ LAYOUT FIX · nav flush + compact side fabs + heading flourishes ═══ */
.blog-head{padding:0!important}
#page_list_top{padding-bottom:clamp(12px,2vw,20px)}
.tabs{padding-top:10px}
.fab-stack{gap:6px}
.fab,.fab-stack #toTop{width:38px;height:38px;background:var(--accent-soft);border:1px solid rgba(156,69,34,.3);color:var(--accent-dark);box-shadow:0 10px 22px -16px rgba(36,22,16,.55)}
.fab svg{width:15px;height:15px}
.fab:hover{background:var(--accent);border-color:var(--accent);color:#FFF6E8;transform:translateY(-2px)}
.fab-divider{width:16px}
@media (max-width:760px){.fab-stack{gap:5px;right:8px}.fab,.fab-stack #toTop{width:34px;height:34px}.fab svg{width:14px;height:14px}.fab-divider{width:1px;height:16px}}
@keyframes tRise{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}
@keyframes tLine{to{transform:scaleX(1)}}
.item-post .post-title{position:relative;animation:tRise .7s var(--ease) both}
.item-post .post-title::after{content:"";display:block;width:76px;height:3.5px;border-radius:3px;background:var(--accent);margin-top:14px;transform:scaleX(0);transform-origin:left;animation:tLine .7s var(--ease) .4s forwards}
.post-body h2,.page-body h2,.wrap h2{position:relative}
.post-body h2::after,.page-body h2::after,.wrap h2::after{content:"";position:absolute;left:0;bottom:-7px;width:54px;height:3px;border-radius:3px;background:var(--accent);transform:scaleX(1);transform-origin:left}
h2.hPend{opacity:0;transform:translateY(18px)}
h2.hPend::after{transform:scaleX(0);transition:none}
h2.hIn{opacity:1;transform:none;transition:opacity .6s var(--ease),transform .6s var(--ease)}
h2.hIn::after{transform:scaleX(1)}
@media (prefers-reduced-motion:reduce){.item-post .post-title,.item-post .post-title::after{animation:none;transform:none}h2.hPend{opacity:1;transform:none}h2.hPend::after{transform:scaleX(1)}}

/* ═══ GLOBAL OVERRIDES · one consistent system on every page, post, label ═══ */
.topbar-inner{height:clamp(78px,9vw,96px)}
.topbar-title{font-size:clamp(24px,4vw,38px)!important;letter-spacing:.08em!important}
@media (max-width:560px){.topbar-title{font-size:clamp(19px,5.4vw,23px)!important;letter-spacing:.05em!important}}
.fd-col>a{display:block!important;padding:4px 0}
.tabs li.selected a,.tabs li.selected a:hover{background:var(--accent-dark)!important;color:#FFFFFF!important;border-color:var(--accent-dark)!important}
.blog-posts h3.post-title a{background:linear-gradient(var(--accent),var(--accent)) no-repeat 0 100%/0 2px;transition:background-size .4s var(--ease),color .3s var(--ease)}
.blog-posts h3.post-title a:hover{background-size:100% 2px;color:var(--accent-dark)}
.wrap h3.hPend{opacity:0;transform:translateY(14px)}
.wrap h3.hIn{opacity:1;transform:none;transition:opacity .6s var(--ease),transform .6s var(--ease)}

/* ═══ HEADER ALIGN FIX · squiggle under the typed word, uniform pills ═══ */
.tb-line{position:relative;display:inline-flex;align-items:baseline;gap:4px}
.tb-squig{left:50%;transform:translateX(-50%);bottom:-10px;width:clamp(68px,8vw,98px);height:8px}
.tabs{align-items:center}
.tabs li{display:flex;align-items:center}
.tabs a{line-height:1}
.kv-squig{margin:10px 0 0 2px}

/* ═══ FLIP ALIGN · word sits on the line, squiggle at constant distance ═══ */
.kv-flip{height:1.26em;vertical-align:bottom;align-items:end}
.kv-word{line-height:1.26;display:block;height:100%}
.kv-squig{margin:13px 0 0 2px}





/* ═══ FEATURE WALL v6 · 200 stickers · ink/brown/copper · depth blur · endless wander ═══ */
@keyframes fwIn{from{opacity:0}to{opacity:var(--o,.15)}}
@keyframes fwJourney{0%{transform:translate(0,0) rotate(var(--r,0deg))}25%{transform:translate(calc(var(--dx,8px)*.8),calc(var(--dy,-9px)*1.1)) rotate(calc(var(--r,0deg) + var(--tw,7deg)))}50%{transform:translate(calc(var(--dx,8px)*1.35),calc(var(--dy,-9px)*-.25)) rotate(calc(var(--r,0deg) - var(--tw,7deg)*.6))}75%{transform:translate(calc(var(--dx,8px)*.4),calc(var(--dy,-9px)*-.9)) rotate(calc(var(--r,0deg) + var(--tw,7deg)*.4))}100%{transform:translate(0,0) rotate(var(--r,0deg))}}
.fin-wall{position:relative;overflow:hidden;height:clamp(200px,26vw,290px);background:radial-gradient(70% 130% at 12% 0%,rgba(246,227,211,.55) 0%,rgba(246,227,211,0) 55%),radial-gradient(60% 120% at 92% 100%,rgba(246,227,211,.5) 0%,rgba(246,227,211,0) 55%),radial-gradient(rgba(156,69,34,.07) 1px,transparent 1.2px);background-size:auto,auto,24px 24px;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
.fin-wall i{position:absolute;opacity:0;animation:fwIn 1.1s ease forwards,fwJourney var(--wd,16s) ease-in-out infinite}
.fin-wall i svg{width:100%;height:100%;stroke:currentColor;fill:none;stroke-width:1.55;stroke-linecap:round;stroke-linejoin:round}
.fin-wall i.t-ink{color:#2A1C12}
.fin-wall i.t-brown{color:#6B4A2E}
.fin-wall i.t-copper{color:#C9955C}
.fin-wall i.b{filter:blur(1.4px)}
.fin-wall i.m{filter:blur(.4px)}
.fin-wall i.f{filter:none}

.fin-wall .flow{position:absolute;inset:0;width:100%;height:100%;pointer-events:none}
.fin-wall .flow path{fill:none;stroke:rgba(156,69,34,.17);stroke-width:1.5;stroke-linecap:round;stroke-dasharray:.5 9}
@media (max-width:560px){.fin-wall{height:190px}.fin-wall i.b{filter:blur(1px)}}
@media (prefers-reduced-motion:reduce){.fin-wall i{animation:none;opacity:var(--o,.15)}}

/* ADDITIVE ENHANCEMENTS — original skin above is unchanged. */
/* Additive edition: original page skins stay intact. Only new .enh-* elements use this skin. */
#enhancedHome{position:relative;max-width:1180px;margin:auto;--eh-ink:#2b1d15;--eh-accent:#a4512d;--eh-line:#e1caab;--eh-paper:#fffaf0}
#enhancedHome .enh-toolbar{display:flex;justify-content:space-between;align-items:center;gap:14px;padding:10px 8px;margin-bottom:8px;border-bottom:1px dashed #d9c4a4;color:#947557;font:600 9px/1.5 Inter,Arial,sans-serif;letter-spacing:.1em;text-transform:uppercase}#enhancedHome .enh-toolbar a{color:inherit;text-decoration:none}#enhancedHome .enh-effects{font:600 10px/1.5 Inter,Arial,sans-serif;padding:7px 12px;border:1px solid #d9c4a4;background:#fff9ee;color:#8a4429;border-radius:30px;cursor:pointer;white-space:nowrap}
#enhancedHome .enh-announcement{display:flex;align-items:center;justify-content:space-between;gap:12px;border-block:1px dashed #d8bc99;padding:13px 18px;background:#f2dfbf40;margin:20px 0;color:#8a5233;font:500 11px/1.8 Inter,Arial,sans-serif}#enhancedHome .enh-announcement a{color:#9c4522;font-weight:700;text-decoration:none;white-space:nowrap}
#enhancedHome .enh-module{position:relative;isolation:isolate;margin:45px 0 20px;padding:clamp(23px,3.8vw,44px);border:1px solid #dec6a4;border-radius:5px 22px 5px 22px;background:radial-gradient(ellipse at 100% 0,#e6c29638,transparent 50%),#fffaf0;color:#2b1d15;box-shadow:0 25px 55px -45px #805333;overflow:hidden;font:14px/1.8 Inter,Arial,sans-serif;scroll-margin-top:50px}
#enhancedHome .enh-module::before{content:'';position:absolute;inset:9px;border:1px solid #c9a77833;border-radius:2px 16px 2px 16px;pointer-events:none;z-index:-1}#enhancedHome .enh-module *{box-sizing:border-box}#enhancedHome .enh-kicker{display:block;font:700 9px/1.5 Inter,Arial,sans-serif;letter-spacing:.2em;text-transform:uppercase;color:#a4512d;margin-bottom:13px}
#enhancedHome .enh-module h2{font:600 clamp(26px,3.4vw,39px)/1.2 'Playfair Display',Georgia,serif;color:#2b1d15;margin:0 0 15px;letter-spacing:-.025em}#enhancedHome .enh-module h2 em{color:#a4512d;font-weight:500}#enhancedHome .enh-intro{font:400 13px/1.85 Inter,Arial,sans-serif;color:#79624e;max-width:810px;margin:0 0 26px}#enhancedHome .enh-module h3{font:600 23px/1.3 'Playfair Display',Georgia,serif;margin:0 0 12px;color:#2b1d15}
#enhancedHome .enh-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px}#enhancedHome .enh-card{--rx:0deg;--ry:0deg;position:relative;display:block;min-width:0;padding:24px 22px;border:1px solid #e2cdb0;border-radius:13px;background:#fffdf6;color:#2b1d15;text-decoration:none!important;transform:perspective(800px) rotateX(var(--rx)) rotateY(var(--ry));transition:transform .25s ease,box-shadow .25s ease,border-color .25s ease;overflow:hidden;isolation:isolate}#enhancedHome .enh-card::after{content:'';position:absolute;inset:-40%;background:linear-gradient(110deg,transparent 40%,#dba75a13 50%,transparent 60%);transform:translateX(-70%);pointer-events:none;z-index:-1}#enhancedHome .enh-card:hover{border-color:#bd8b56;box-shadow:0 18px 30px -25px #995f2a}#enhancedHome .enh-card:hover::after{animation:enh-shine 1.1s ease}
#enhancedHome .enh-card p{font:400 12px/1.85 Inter,Arial,sans-serif;color:#816953;margin:0 0 20px}#enhancedHome .enh-card small{font:700 10px/1.6 Inter,Arial,sans-serif;letter-spacing:.04em;color:#9c4522}#enhancedHome .enh-icon{display:block;width:44px;height:44px;margin-bottom:23px;fill:none;stroke:#a75c35;stroke-width:1.35;stroke-linecap:round;stroke-linejoin:round}#enhancedHome .enh-icon path{stroke-dasharray:160;stroke-dashoffset:0}#enhancedHome .enh-card:hover .enh-icon path{animation:enh-draw 1.3s ease}
#enhancedHome .enh-trail{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:0;margin:25px 0 8px;border:1px solid #d9bf98;border-radius:12px;overflow:hidden}#enhancedHome .enh-trail div{padding:22px;border-right:1px dashed #d9bf98;background:#f7ead1}#enhancedHome .enh-trail div:last-child{border:0}#enhancedHome .enh-trail b{display:block;font:italic 28px/1.1 Georgia,serif;color:#ad683d;margin-bottom:10px}#enhancedHome .enh-trail strong{display:block;font-size:12px;color:#5f3f26;margin-bottom:7px}#enhancedHome .enh-trail span{font-size:11px;line-height:1.8;color:#806346}
#enhancedHome .enh-tabs{display:flex;flex-wrap:wrap;gap:8px;margin:24px 0 18px}#enhancedHome .enh-tab{font:600 11px/1.5 Inter,Arial,sans-serif;color:#895032;border:1px solid #d7bc97;background:#fffaf0;padding:10px 15px;border-radius:25px;cursor:pointer}#enhancedHome .enh-tab[aria-selected=true]{background:#352319;border-color:#352319;color:#fff2df}#enhancedHome .enh-panel{display:grid;grid-template-columns:1.1fr 1fr;gap:28px;padding:25px;background:repeating-linear-gradient(transparent 0 31px,#a4754120 32px),#f6e8cf;border:1px solid #dfc5a0;border-radius:4px 16px 4px 16px}#enhancedHome .enh-panel[hidden]{display:none!important}#enhancedHome .enh-panel h3{font-size:27px}#enhancedHome .enh-panel p{font-size:13px;line-height:1.85;color:#715235;margin:0 0 12px}#enhancedHome .enh-panel ul{margin:0;padding-left:17px;font:12px/1.9 Inter,Arial,sans-serif;color:#806044}#enhancedHome .enh-panel a{color:#954a28;font-weight:700;font-size:11px}#enhancedHome .enh-panel.enh-selected{animation:enh-note .45s ease}
#enhancedHome .enh-details{margin:14px 0 0;border-top:1px dashed #ccb08a;padding:14px 0;font:12px/1.85 Inter,Arial,sans-serif;color:#775b43}#enhancedHome .enh-details summary{cursor:pointer;font-weight:700;color:#6d472b}#enhancedHome .enh-fine{font:400 10px/1.75 Inter,Arial,sans-serif;color:#92765c;margin:18px 0 0}#enhancedHome .enh-callout{padding:16px 20px;border-left:3px solid #af6036;border-radius:0 9px 9px 0;background:#efe0c5;margin:20px 0;font:12px/1.85 Inter,Arial,sans-serif;color:#805932}
#enhancedHome .enh-footer{margin:40px 0 10px;padding:25px 10px;border-top:1px solid #dfc8a8;font:11px/1.8 Inter,Arial,sans-serif;color:#99734e}#enhancedHome .enh-footer>span{font:italic 22px/1.4 Georgia,serif;color:#a05530;display:block;margin-bottom:18px}#enhancedHome .enh-footer nav{display:flex;flex-wrap:wrap;gap:8px 19px}#enhancedHome .enh-footer a{color:inherit;text-decoration:none}
#enhancedHome .enh-reading-line{position:fixed;top:0;left:0;height:2px;width:0;z-index:99999;background:linear-gradient(90deg,#9c4522,#d4a15b);pointer-events:none}#enhancedHome .enh-pulse{animation:enh-pulse .6s ease}#enhancedHome [data-enhanced-note]{position:relative}
/* Keep the original page's revelation effects visible in standalone and sandbox previews. */
#enhancedHome .reveal,#enhancedHome .reveal.will-reveal{opacity:1;visibility:visible}#enhancedHome .enh-in{animation:enh-enter .65s cubic-bezier(.2,.7,.2,1) both}
/* Preserve the approved left/right heroes without flattening their original skins. */
#enhancedHome .kvP-in,#enhancedHome .kc-htop{display:grid!important;grid-template-columns:minmax(0,1.08fr) minmax(0,.92fr)!important;gap:clamp(14px,3vw,38px)!important;align-items:center}#enhancedHome .kvP-in>*,#enhancedHome .kc-htop>*{min-width:0;max-width:100%;width:100%}#enhancedHome .kvP-in>.kvP-panel,#enhancedHome .kc-htop>.kcd-panel{max-width:370px!important;justify-self:end}#enhancedHome .kvP-in .kvP-h1,#enhancedHome .kc-htop h1{font-size:clamp(26px,4.5vw,54px)}
#enhancedHome .kc-guide{grid-template-columns:repeat(2,minmax(0,1fr))}#enhancedHome .kc-guide>*{min-width:0}#enhancedHome .kc-pick>*{min-width:0;white-space:normal;overflow-wrap:anywhere}#enhancedHome .kc-locale label{min-width:0;max-width:100%;flex-wrap:wrap}#enhancedHome .kc-locale select{min-width:0;max-width:100%}
#enhancedHome .enh-controls :focus-visible,#enhancedHome .enh-module :focus-visible,#enhancedHome .enh-toolbar :focus-visible{outline:3px solid #ac6237;outline-offset:4px}
#enhancedHome[data-effects=paused] *,#enhancedHome[data-effects=paused] *::before,#enhancedHome[data-effects=paused] *::after{animation-play-state:paused!important;transition:none!important}
@keyframes enh-enter{from{opacity:.6;transform:translateY(15px)}to{opacity:1;transform:translateY(0)}}@keyframes enh-shine{to{transform:translateX(70%)}}@keyframes enh-draw{from{stroke-dashoffset:160}to{stroke-dashoffset:0}}@keyframes enh-note{from{opacity:.55;transform:translateY(8px) rotate(-.3deg)}to{opacity:1;transform:none}}@keyframes enh-pulse{30%{box-shadow:0 0 0 4px #b4743130}}
.post-body #enhancedHome{width:100%!important;max-width:1180px!important}.post-body #enhancedHome .enh-module,.post-body #enhancedHome .enh-grid,.post-body #enhancedHome .enh-panel,.post-body #enhancedHome .enh-trail{width:100%!important;max-width:100%!important}.post-body #enhancedHome .enh-card,.post-body #enhancedHome .enh-panel>*,.post-body #enhancedHome .enh-trail>*{width:100%!important;max-width:100%!important;min-width:0!important}.post-body #enhancedHome .kvP-in>*,.post-body #enhancedHome .kc-htop>*{width:100%!important;max-width:100%!important;min-width:0!important}.post-body #enhancedHome .kvP-in>.kvP-panel,.post-body #enhancedHome .kc-htop>.kcd-panel{max-width:370px!important}
@media(max-width:700px){#enhancedHome .enh-grid{grid-template-columns:repeat(2,minmax(0,1fr))}#enhancedHome .enh-panel{grid-template-columns:1fr;gap:12px;padding:20px}#enhancedHome .enh-trail{grid-template-columns:1fr}#enhancedHome .enh-trail div{border-right:0;border-bottom:1px dashed #d9bf98;padding:18px 22px}#enhancedHome .enh-module{padding:25px 19px;margin:30px 0 15px}#enhancedHome .enh-announcement{font-size:10px;align-items:start}#enhancedHome .enh-announcement a{white-space:normal}#enhancedHome .kvP-in .kvP-h1,#enhancedHome .kc-htop h1{font-size:clamp(24px,5.8vw,34px)!important}#enhancedHome .kvP-in .kvP-lede,#enhancedHome .kc-htop .kc-lede{font-size:12px;line-height:1.7}#enhancedHome .kvP-in .kvP-panel,#enhancedHome .kc-htop .kcd-panel{padding:12px 10px!important}#enhancedHome .kvP-in .kvP-slide,#enhancedHome .kc-htop .kcd-slide{padding:12px 8px!important}#enhancedHome .kvP-in .kvP-srow,#enhancedHome .kvP-in .kvP-lrow,#enhancedHome .kc-htop .kcd-srow{font-size:10px!important;line-height:1.5;gap:5px;flex-wrap:wrap}#enhancedHome .kvP-in .kvP-lrow>b,#enhancedHome .kc-htop .kcd-srow>b{font-size:12px!important;white-space:normal}#enhancedHome .kvP-in .kvP-caveat,#enhancedHome .kc-htop .kcd-caveat{font-size:18px!important}#enhancedHome .kvP-in .kvP-fine{font-size:10px!important}#enhancedHome .kc-guide{grid-template-columns:minmax(0,1fr)}#enhancedHome .kc-locale label{width:100%}#enhancedHome .kc-locale select{flex:1 1 120px}}
@media(max-width:450px){#enhancedHome .enh-grid{grid-template-columns:1fr}#enhancedHome .enh-card{padding:22px}#enhancedHome .enh-icon{margin-bottom:14px}#enhancedHome .enh-module{padding:25px 16px}#enhancedHome .enh-toolbar{font-size:8px}#enhancedHome .enh-effects{font-size:9px}}
