b:if.script:
//
(function(){
 var d = document;
 /* KV hero : rotating word + 20-slide card */
 var flip = d.getElementById('kvFlip');
 if (flip){
 var kw = [].slice.call(flip.children), ki = 0;
 setInterval(function(){
 var cur = kw[ki]; ki = (ki + 1) % kw.length;
 var nx = kw[ki];
 cur.classList.remove('on'); cur.classList.add('out');
 setTimeout(function(){ cur.classList.remove('out'); }, 650);
 nx.classList.add('on');
 }, 2000);
 }
 var track = d.getElementById('kvTrack');
 if (track){
 var panes2 = track.children, kn = panes2.length, ki2 = 0, ktimer = null;
 var kbar = d.getElementById('kvBar');
 function kvBar(){ if (!kbar) return; kbar.style.transition = 'none'; kbar.style.width = '0%';
 void kbar.offsetWidth; kbar.style.transition = 'width 3s linear'; kbar.style.width = '100%'; }
 function kvGo(n){
 ki2 = (n + kn) % kn;
 track.style.transform = 'translateX(-' + (ki2 * 100) + '%)';
 kvBar();
 }
 function kvAuto(){ if (ktimer) clearInterval(ktimer); ktimer = setInterval(function(){ kvGo(ki2 + 1); }, 3000); }
 var kc = d.getElementById('kvCalc');
 if (kc) kc.addEventListener('click', function(){ kvGo(ki2 + 1); kvAuto(); });
 var kvx0 = null;
 track.addEventListener('touchstart', function(e){ kvx0 = e.touches[0].clientX; }, {passive:true});
 track.addEventListener('touchend', function(e){
 if (kvx0 === null) return;
 var dx = e.changedTouches[0].clientX - kvx0; kvx0 = null;
 if (dx < -40){ kvGo(ki2 + 1); kvAuto(); } else if (dx > 40){ kvGo(ki2 - 1); kvAuto(); }
 }, {passive:true});
 var kexp = d.getElementById('kvExplore');
 if (kexp) kexp.addEventListener('click', function(e){ var t = d.getElementById('Blog1'); if (t){ e.preventDefault(); t.scrollIntoView({ behavior: 'smooth' }); } });
 d.addEventListener('keydown', function(e){
 if (e.key === 'ArrowRight'){ kvGo(ki2 + 1); kvAuto(); }
 if (e.key === 'ArrowLeft'){ kvGo(ki2 - 1); kvAuto(); }
 });
 kvGo(0); kvAuto();
 }
})();
