body.script:
//
//
(function(){
 var d = document, root = d.documentElement;

 /* Drawer sidebar */
 var dt = d.getElementById('drawerToggle'), sb = d.getElementById('sidebarBack'), sc = d.getElementById('scrim');
 function closeDrawer(){ root.classList.remove('drawer-open'); if (dt) dt.setAttribute('aria-expanded','false'); }
 if (dt) dt.addEventListener('click', function(){
 var open = root.classList.toggle('drawer-open');
 dt.setAttribute('aria-expanded', open ? 'true' : 'false');
 if (open) root.classList.remove('search-open');
 });
