if(dk&&!dk.getAttribute('data-dup')){dk.setAttribute('data-dup','1');requestAnimationFrame(function(){var wr=D.getElementById('kdDeskWrap');if(wr&&dk.scrollWidth<=wr.clientWidth+8)return;var cp=dk.innerHTML;dk.insertAdjacentHTML('beforeend','<span aria-hidden="true" style="display:contents">'+cp+'</span>');});}
